(function() {
    const $dropdownBtn = document.getElementById('selectThemeDropdown')
    const $variants = document.querySelectorAll(`[aria-labelledby="selectThemeDropdown"] [data-icon]`)

    const setActiveStyle = function () {
        $variants.forEach($item => {
            if ($item.getAttribute('data-value') === NueThemeAppearance.getOriginalAppearance()) {
                $dropdownBtn.innerHTML = `<span class="iconify i-2x" data-icon="${$item.getAttribute('data-icon')}" ></span>`
                return $item.classList.add('active')
            }

            $item.classList.remove('active')
        })
    }

    $variants.forEach(function ($item) {
        $item.addEventListener('click', function () {
            NueThemeAppearance.setAppearance($item.getAttribute('data-value'))
        })
    })

    setActiveStyle()

    window.addEventListener('on-nue-appearance-change', function () {
        setActiveStyle()
    })
})()